// Review desk helper: approval coverage rows, access assurance rows and the application portfolio tiles.
// Runs on records.onDataQuerySuccess, masters.onDataQuerySuccess and Review desk onPageLoad. Carries the template's access rules once.
const e = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'}[c]));
const all = queries.records.data || [], apps = queries.masters.data || [];
const utcDay = () => new Date().toISOString().slice(0, 10);
const policy = a => ({ maxDays: 90, roles: [], securityOwner: (a && a.owner) || '', ...((a && a.policy) || {}) });
const gov = r => ({ requestRevision: 0, startDate: '', privileged: false, certifications: [], ...((r && r.governance) || {}) });
const roles = (r, a) => ['manager', 'owner', ...((gov(r).privileged || (a && a.sensitivity === 'Restricted')) ? ['security'] : [])];
const approvals = (r, a) => roles(r, a).filter(id => { const q = ((r && r.reviews) || []).filter(q => q.id === id).slice(-1)[0]; return !!q && q.decision === 'Approved' && q.requestRevision === gov(r).requestRevision && gov(r).requestRevision > 0; });
const reviewDue = r => { const g = gov(r); return ['Active', 'Revocation due'].includes(r.status) && (r.status === 'Revocation due' || !g.nextReviewDate || g.nextReviewDate <= utcDay() || r.expires < utcDay()); };
const initials = s => String(s || '').split(' ').map(v => v[0]).slice(0, 2).join('');
const chip = (label, color, bg) => "<span style='display:inline-block;width:100%;text-align:center;padding:6px 2px;border-radius:6px;font-size:10px;font-weight:600;color:" + color + ";background:" + bg + ";'>" + label + "</span>";
// Approval coverage: open requests, earliest access end date first
const q = all.filter(x => ['In review', 'Approved'].includes(x.status)).slice().sort((a, b) => String(a.expires).localeCompare(String(b.expires)));
const rows = q.slice(0, 3).map(x => {
  const a = apps.find(a => a.name === x.application), approved = approvals(x, a), required = roles(x, a);
  const cell = id => {
    const yes = approved.includes(id), needed = required.includes(id);
    const d = (x.reviews || []).find(y => y.id === id);
    const rejected = !!d && d.decision === 'Rejected' && d.requestRevision === gov(x).requestRevision;
    return chip(yes ? '✓ Approved' : rejected ? 'Rejected' : needed ? '◷ Pending' : '—',
      yes ? 'var(--cc-success-systemStatus)' : rejected ? 'var(--cc-error-systemStatus)' : needed ? 'var(--cc-primary-brand)' : 'var(--cc-placeholder-text)',
      needed ? 'var(--cc-surface3-surface)' : 'transparent');
  };
  return { id: x.id, empty: false, initials: e(initials(x.name)), name: x.name, appRole: (x.application || '') + ' · ' + (x.access_role || ''), refLine: e(x.reference) + ' / ' + e(x.expires), chipM: cell('manager'), chipO: cell('owner'), chipS: cell('security') };
});
if (!rows.length) rows.push({ id: null, empty: true, initials: '', name: 'No requests awaiting approval or fulfillment.', appRole: '', refLine: '', chipM: '', chipO: '', chipS: '' });
// Access assurance: grants requiring an owner's attention
const due = all.filter(reviewDue).slice().sort((a, b) => String(a.expires).localeCompare(String(b.expires)));
const dueRows = due.slice(0, 3).map(x => {
  const revoke = x.status === 'Revocation due', expired = x.expires < utcDay();
  return { name: x.name, tag: revoke ? 'Remove access' : expired ? 'Expired' : 'Review due', tagColor: (revoke || expired) ? 'var(--cc-error-systemStatus)' : 'var(--cc-primary-brand)', application: x.application || '', role: x.access_role || '', expires: x.expires || '' };
});
if (!dueRows.length) dueRows.push({ name: 'No access reviews currently due.', tag: '', tagColor: 'var(--cc-primary-brand)', application: '', role: '', expires: '' });
// Application portfolio: top four applications by active grants, then by having a policy
const activeOf = a => all.filter(x => x.application === a.name && ['Active', 'Revocation due'].includes(x.status)).length;
const pendingOf = a => all.filter(x => x.application === a.name && ['In review', 'Approved'].includes(x.status)).length;
const ranked = apps.slice().sort((a, b) => activeOf(b) - activeOf(a) || Number(!!b.policy) - Number(!!a.policy)).slice(0, 4);
const out = {
  openCount: q.length,
  footer: q.filter(x => x.status === 'Approved').length + ' ready for fulfillment · Showing ' + Math.min(q.length, 3) + ' of ' + q.length,
  rows, dueCount: due.length, dueRows,
  appsLabel: apps.length + ' applications · Access ownership and policy'
};
ranked.forEach((a, i) => {
  const active = activeOf(a), pending = pendingOf(a), total = active + pending;
  out['t' + i + 'i'] = e(initials(a.name)); out['t' + i + 'n'] = a.name; out['t' + i + 'm'] = (a.owner || '') + ' · ' + (a.sensitivity || '');
  out['t' + i + 'a'] = active; out['t' + i + 'p'] = pending + ' pending'; out['t' + i + 'pct'] = total ? Math.round(active / total * 100) : 0;
  out['t' + i + 'y'] = 'Maximum term ' + policy(a).maxDays + ' days · ' + (a.availability || '');
});
return out;

// Request workspace helper: the selected request's summary card, scope & assurance text and decision history. Carries the access rules once.
// Runs on records.onDataQuerySuccess, masters.onDataQuerySuccess and Request workspace onPageLoad.
const e = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'}[c]));
const all = queries.records.data || [], apps = queries.masters.data || [];
const policy = a => ({ maxDays: 90, roles: [], securityOwner: (a && a.owner) || '', ...((a && a.policy) || {}) });
const gov = r => ({ requestRevision: 0, startDate: '', privileged: false, certifications: [], ...((r && r.governance) || {}) });
const roles = (r, a) => ['manager', 'owner', ...((gov(r).privileged || (a && a.sensitivity === 'Restricted')) ? ['security'] : [])];
const approvals = (r, a) => roles(r, a).filter(id => { const q = ((r && r.reviews) || []).filter(q => q.id === id).slice(-1)[0]; return !!q && q.decision === 'Approved' && q.requestRevision === gov(r).requestRevision && gov(r).requestRevision > 0; });
const withinPolicy = (r, a) => { const g = gov(r), p = policy(a), start = Date.parse(g.startDate + 'T00:00:00Z'), end = Date.parse(String(r && r.expires) + 'T00:00:00Z'); return !!a && a.availability === 'Open' && Number.isFinite(start) && Number.isFinite(end) && end >= start && (end - start) / 86400000 <= p.maxDays && (!p.roles.length || p.roles.includes(r.access_role)); };
const initials = s => String(s || '').split(' ').map(v => v[0]).slice(0, 2).join('');
const x = all.find(r => r.id === variables.recordId);
if (!x) return { has: false, name: 'Choose a request from the review desk.', initials: '', refLine: '', email: '', kind: '', application: '', role: '', dates: '', status: '', decisions: '', pct: 0, policyLine: '', scopeHtml: '', history: [] };
const g = gov(x), a = apps.find(a => a.name === x.application), n = approvals(x, a).length, total = roles(x, a).length;
const certs = (g.certifications || []).slice().reverse().map(c => "<p style='font-size:12px;line-height:19px;border-top:1px solid var(--cc-default-border);padding-top:10px;margin:10px 0 0;'><b>" + e(c.outcome) + "</b> · " + e(c.reviewer) + "<br>" + e(c.note) + "<br><small>Next review " + e(c.nextReviewDate) + "</small></p>").join('');
const scopeHtml = "<p style='font-size:12px;line-height:20px;margin:0 0 8px;'>" + e(x.summary) + "</p><div style='font-size:11px;color:var(--cc-placeholder-text);line-height:19px;'>" + e(x.provisioning || 'No provisioning evidence yet.') + "<br>" + e(x.revocation || '') + "</div>" + certs;
return {
  has: true,
  name: x.name,
  initials: e(initials(x.name)),
  refLine: e(x.reference) + ' / SCOPE ' + g.requestRevision,
  email: x.email || '',
  kind: (g.privileged ? 'Privileged' : 'Standard') + ' access',
  application: x.application || '',
  role: x.access_role || '',
  dates: (g.startDate || 'Confirm start') + ' → ' + (x.expires || ''),
  status: x.status || '',
  decisions: n + ' of ' + total + ' current decisions',
  pct: total ? Math.round(n / total * 100) : 0,
  policyLine: withinPolicy(x, a) ? 'Scope within application policy' : 'Scope requires policy review',
  scopeHtml,
  history: (x.history || []).slice().reverse().map(h => ({ event: h.event || '', note: h.note || '' }))
};
